const bodySource = $('Public Legal Consultation Webhook').first().json.body || $('Public Legal Consultation Webhook').first().json || {};
let body = bodySource;
if (typeof bodySource.payload === 'string') {
  try { body = JSON.parse(bodySource.payload); } catch (_) { return [{ json: { ok: false, operation: 'respond', statusCode: 400, message: 'Invalid payload JSON.' } }]; }
}
const action = String(body.action || '').trim();
const data = body.data || {};
const F = { id: '\u9810\u7d04\u7de8\u865f', name: '\u59d3\u540d', phone: '\u96fb\u8a71', statement: '\u4e8b\u4ef6\u9673\u8ff0', category: '\u6cd5\u6276\u9805\u76ee', case1999: '1999\u6848\u865f', slot: '\u6307\u5b9a\u9810\u7d04\u6642\u9593', date: '\u9810\u7d04\u65e5\u671f', status: '\u72c0\u614b' };
const CATEGORY_FIELD = { '\u6c11\u4e8b': '\u6c11\u4e8b', '\u5211\u4e8b': '\u5211\u4e8b', '\u884c\u653f\u8a34\u8a1f': '\u884c\u653f\u8a34\u8a1f', '\u5bb6\u4e8b': '\u5bb6\u4e8b', '\u52de\u8cc7\u7cfe\u7d1b': '\u52de\u8cc7\u7cfe\u7d1b', '\u6d88\u8cbb\u7cfe\u7d1b': '\u6d88\u8cbb\u7cfe\u7d1b', '\u5f37\u5236\u57f7\u884c': '\u5f37\u5236\u57f7\u884c' };
function text(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(text).filter(Boolean).join('');
  if (value.plain_text) return String(value.plain_text);
  if (value.text?.content) return String(value.text.content);
  if (value.name) return String(value.name);
  if (value.title) return text(value.title);
  if (value.rich_text) return text(value.rich_text);
  if (value.select) return text(value.select);
  if (value.multi_select) return text(value.multi_select);
  if (value.date) return value.date.start || '';
  if (value.phone_number) return value.phone_number || '';
  return '';
}
function prop(json, names) {
  const wanted = Array.isArray(names) ? names : [names];
  for (const name of wanted) {
    if (json[name] != null) return text(json[name]).trim();
    if (json.properties?.[name] != null) return text(json.properties[name]).trim();
  }
  return '';
}
const rawPages = items.map(item => item.json || {});
const pages = rawPages.filter(page => prop(page, F.id) !== '__LEGAL_SLOT_SETTINGS__');
const settingsPage = rawPages.find(page => prop(page, F.id) === '__LEGAL_SLOT_SETTINGS__');
function dateSlots(dateValue) {
  const day = new Date(dateValue + 'T00:00:00').getDay();
  if (day < 1 || day > 5) return [];
  const hour = day === 3 ? '10' : '15';
  return [hour + ':00', hour + ':15', hour + ':30', hour + ':45'];
}
function dayKey(dateValue, time) {
  const day = new Date(dateValue + 'T00:00:00').getDay();
  return day + '-' + String(time || '').slice(0, 5);
}
function slotSettings() {
  if (!settingsPage) return { disabledSlots: [] };
  try {
    const parsed = JSON.parse(prop(settingsPage, F.statement) || '{}');
    return { disabledSlots: Array.isArray(parsed.disabledSlots) ? parsed.disabledSlots.map(String) : [] };
  } catch (_) { return { disabledSlots: [] }; }
}
function slotLabel(dateValue, time) {
  const day = new Date(dateValue + 'T00:00:00').getDay();
  return ['\u661f\u671f\u65e5','\u661f\u671f\u4e00','\u661f\u671f\u4e8c','\u661f\u671f\u4e09','\u661f\u671f\u56db','\u661f\u671f\u4e94','\u661f\u671f\u516d'][day] + ' ' + time;
}
function rocDateKey(dateValue) {
  const parts = String(dateValue).slice(0, 10).split('-').map(Number);
  return String(parts[0] - 1911).padStart(3, '0') + String(parts[1]).padStart(2, '0') + String(parts[2]).padStart(2, '0');
}
function nextAppointmentId(dateValue) {
  const prefix = rocDateKey(dateValue);
  const max = pages.map(page => prop(page, F.id)).filter(id => id.startsWith(prefix)).map(id => Number(id.slice(prefix.length))).filter(Number.isFinite).reduce((a, b) => Math.max(a, b), 0);
  return prefix + String(max + 1).padStart(3, '0');
}
function response(payload, statusCode = 200) { return [{ json: { operation: 'respond', statusCode, ...payload } }]; }
if (action === 'availability') {
  const dateValue = String(data.appointmentDate || '').slice(0, 10);
  const allSlots = dateSlots(dateValue);
  const disabled = new Set(slotSettings().disabledSlots);
  const closedSlots = allSlots.filter(slot => disabled.has(dayKey(dateValue, slot)));
  const bookedSlots = pages.filter(page => prop(page, F.status) === 'confirmed').filter(page => prop(page, F.date).startsWith(dateValue)).map(page => prop(page, F.date).slice(11, 16)).filter(Boolean);
  const availableSlots = allSlots.filter(slot => !closedSlots.includes(slot) && !bookedSlots.includes(slot));
  return response({ ok: true, availableSlots, bookedSlots, closedSlots, slots: allSlots.map(time => ({ time, label: slotLabel(dateValue, time), available: availableSlots.includes(time), closed: closedSlots.includes(time), booked: bookedSlots.includes(time) })) });
}
if (action === 'book') {
  const dateValue = String(data.appointmentDate || '').slice(0, 10);
  const timeValue = String(data.appointmentTime || '').slice(0, 5);
  const allSlots = dateSlots(dateValue);
  if (!allSlots.includes(timeValue)) return response({ ok: false, message: '\u6b64\u65e5\u671f\u6216\u6642\u6bb5\u4e0d\u958b\u653e\u9810\u7d04\u3002' }, 400);
  if (new Set(slotSettings().disabledSlots).has(dayKey(dateValue, timeValue))) return response({ ok: false, message: '\u6b64\u6642\u6bb5\u76ee\u524d\u672a\u958b\u653e\u9810\u7d04\uff0c\u8acb\u6539\u9078\u5176\u4ed6\u6642\u9593\u3002' }, 400);
  const duplicate = pages.some(page => prop(page, F.status) === 'confirmed' && prop(page, F.date).startsWith(dateValue) && prop(page, F.date).slice(11, 16) === timeValue);
  if (duplicate) return response({ ok: false, message: '\u6b64\u6642\u6bb5\u5df2\u88ab\u9810\u7d04\uff0c\u8acb\u6539\u9078\u5176\u4ed6\u6642\u9593\u3002' }, 409);
  const appointmentId = nextAppointmentId(dateValue);
  const category = String(data.legalCategory || '').trim();
  const legalItem = String(data.legalItem || '').trim();
  return [{ json: { operation: 'create', ok: true, appointmentId, name: String(data.name || '').trim(), phone: String(data.phone || '').trim(), statement: String(data.statement || '').trim(), case1999: String(data.case1999 || '').trim(), appointmentDateTime: dateValue + 'T' + timeValue + ':00+08:00', slotLabel: slotLabel(dateValue, timeValue), category, legalItem, categoryField: CATEGORY_FIELD[category] || '', legalOtherItem: String(data.legalOtherItem || '').trim(), lineDisplayName: String(data.lineDisplayName || '').trim() } }];
}
if (action === 'query') {
  const appointmentId = String(data.appointmentId || '').trim();
  const page = pages.find(page => prop(page, F.id) === appointmentId);
  if (!page) return response({ ok: false, message: '\u67e5\u7121\u6b64\u9810\u7d04\u8aee\u8a62\u7de8\u865f\u3002' }, 404);
  return response({ ok: true, message: '\u9810\u7d04\u72c0\u614b\uff1a' + (prop(page, F.status) || '\u672a\u8a2d\u5b9a') + '\u3002\u9810\u7d04\u6642\u9593\uff1a' + (prop(page, F.date) || '\u672a\u8a2d\u5b9a'), data: { appointmentId, name: prop(page, F.name), phone: prop(page, F.phone), appointmentDate: prop(page, F.date), status: prop(page, F.status) } });
}
if (action === 'cancel') {
  const appointmentId = String(data.appointmentId || '').trim();
  const page = pages.find(page => prop(page, F.id) === appointmentId);
  if (!page) return response({ ok: false, message: '\u67e5\u7121\u6b64\u9810\u7d04\u8aee\u8a62\u7de8\u865f\u3002' }, 404);
  return [{ json: { operation: 'cancel', ok: true, pageId: page.id, reason: String(data.reason || '').trim(), cancelledAt: new Date().toISOString(), message: '\u53d6\u6d88\u7533\u8acb\u5df2\u9001\u51fa\u3002' } }];
}
return response({ ok: false, message: 'Unsupported action: ' + action }, 400);
